def rootwords(i,extra=()):return list(dict.fromkeys([w for w in ASSIGN['roots'][i]['family'] if w not in DEFERRED and '-' not in w]+list(extra)))
def rootexclude(i):
 r=ASSIGN['roots'][i];c=CATALOG[r['id']];return {w:DEFERRED[w] for w in set(r['family'])|set(c['family'])|set(c['words'])|set(c['unmatched']) if w in DEFERRED}
APHROD_ROOT=dict(id='C0064',meaning='阿佛洛狄忒；与爱欲相关的命名',core='爱与美的女神名，被借来给激起性欲的事物命名。',image='希腊 Aphrodite → Aphrodisios → aphrodisiakos → 拉丁化形式 → 英语 aphrodisiac。',intro='先掌握 aphrodisiac：它可以是催情物质的名称，也可以作形容词。常见文章会把民间名声与真实作用分开，reputed、supposed 之类修饰词要一起读。',forms='aphrod- 主要是保留在女神名相关词里的材料，不是日常可自由拼接的前缀。女神诞生于泡沫的故事是神话解释，不能直接当作确定的语言史。',branches=[['物质名称与所声称的作用','aphrodisiac']],contrasts='词名说明命名与用途，不自行证明某种食物或制剂确有作用。英语先出现名词，不能因为源头是希腊形容词就反转英语词性的出现顺序。',practice='用 supposed aphrodisiac 写一句话，指出 supposed 如何改变作者对这项说法的承诺。',words=rootwords(278),exclude=rootexclude(278))
